local active = {}
local pressing = {}
local lastHit = {}
local btns = {}
local scanRunning = false
local shouldScan = true

for i = 1, 4 do
    pressing[i] = false
    lastHit[i] = 0
end

local function clearConnections()
    for _, c in ipairs(active) do 
        if type(c) == "userdata" and c.Disconnect then 
            pcall(function() c:Disconnect() end)
        end
    end
    active = {}
end

local function runTouch(ln, val)
    local b = btns[ln]
    if not b then return end
    local p = b.AbsolutePosition + (b.AbsoluteSize / 2)
    
    if val then
        vim:SendTouchEvent(ln, 0, p.X, p.Y)
    else
        vim:SendTouchEvent(ln, 2, p.X, p.Y)
    end
end

local function hit(k, val, ln)
    if cfg.mobile then
        runTouch(ln, val)
    else
        vim:SendKeyEvent(val, k, false, game)
    end
    pressing[ln] = val
end

-- close note acc
local function stutter(k, ln)
    if pressing[ln] then
        hit(k, false, ln)
        task.wait(0.001)
    end
end

-- Single note function
local function proc(v, k, l, ln)
    if not v or not v.Parent then return end
    local base = l.AbsolutePosition.Y + l.AbsoluteSize.Y
    local hit_ok = false
    local t = getLong(v)
    local ev 
    ev = rs.RenderStepped:Connect(function()
        if not cfg.ap or not v or not v.Parent or hit_ok then 
            if ev then pcall(function() ev:Disconnect() end) end
            return 
        end
        
        local gap = v.AbsolutePosition.Y - base
        if gap <= cfg.hitPos and gap > (cfg.hitPos - cfg.window) then
            hit_ok = true
            pcall(function() ev:Disconnect() end)
            
            if pressing[ln] and (tick() - lastHit[ln]) < 0.05 then
                stutter(k, ln)
            end
            
            hit(k, true, ln)
            lastHit[ln] = tick()
            
            if t then
                task.spawn(function()
                    while t and t.Parent and cfg.ap do
                        if (t.AbsolutePosition.Y - base) >= cfg.releaseEarly then
                            hit(k, false, ln)
                            break
                        end
                        rs.RenderStepped:Wait()
                    end
                    if pressing[ln] then hit(k, false, ln) end
                end)
            else
                task.spawn(function()
                    task.wait(cfg.tapHold)
                    hit(k, false, ln)
                end)
            end
        end
    end)
    if ev then table.insert(active, ev) end
end

local function scan()
    if scanRunning then return end
    scanRunning = true
    
    while shouldScan do
        clearConnections()
        
        if cfg.mobile then
            task.wait(0.5)
            local root = pg:FindFirstChild("Window")
            root = root and root:FindFirstChild("Game")
            root = root and root:FindFirstChild("TouchInputs")
            
            if root then
                for i = 1, 4 do
                    btns[i] = root:FindFirstChild(tostring(cfg.startLane + i - 1))
                end
            end
        end

        local sw = workspace.CurrentCamera.ViewportSize.X
        local folder = nil
        local dist = math.huge

        for _, v in ipairs(pg:GetDescendants()) do
            if v.Name == "Lane1" and v:FindFirstChild("Notes") then
                local is_left = v.AbsolutePosition.X < (sw / 2)
                if (cfg.startLane == 1 and is_left) or (cfg.startLane == 5 and not is_left) then
                    local d = math.abs(v.AbsolutePosition.X - (sw * 0.25))
                    if d < dist then
                        dist = d
                        folder = v.Parent
                    end
                end
            end
        end

        if folder then
            for i = 1, 4 do
                local l = folder:FindFirstChild("Lane"..(cfg.startLane + i - 1))
                local notes = l and l:FindFirstChild("Notes")
                if notes then
                    for _, v in ipairs(notes:GetChildren()) do
                        if v:IsA("Frame") then 
                            task.spawn(proc, v, cfg.keys[i], l, i) 
                        end
                    end
                    local con = notes.ChildAdded:Connect(function(v)
                        if v:IsA("Frame") then 
                            task.spawn(proc, v, cfg.keys[i], l, i) 
                        end
                    end)
                    if con then table.insert(active, con) end
                end
            end
            while folder and folder.Parent and shouldScan do
                task.wait(0.5)
            end
        else
            task.wait(0.5)
        end
    end
    
    scanRunning = false
end

-- Pulse animation for status indicator
local function pulseIndicator()
    local pulseTween = tws:Create(
        statusIndicator,
        TweenInfo.new(0.8, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut, -1, true),
        {Size = UDim2.new(0, 12, 0, 12)}
    )
    pulseTween:Play()
end

local function anim(isActive)
    -- Status indicator animation
    local targetColor = isActive and Color3.fromRGB(50, 255, 100) or Color3.fromRGB(120, 120, 140)
    local targetStroke = isActive and Color3.fromRGB(100, 255, 150) or Color3.fromRGB(200, 200, 220)
    
    tws:Create(statusIndicator, TweenInfo.new(0.4, Enum.EasingStyle.Quad), {BackgroundColor3 = targetColor}):Play()
    tws:Create(indicatorStroke, TweenInfo.new(0.4, Enum.EasingStyle.Quad), {Color = targetStroke}):Play()
    
    -- Main frame stroke animation
    local frameStroke = isActive and Color3.fromRGB(50, 255, 100) or Color3.fromRGB(100, 100, 120)
    tws:Create(mStroke, TweenInfo.new(0.4, Enum.EasingStyle.Quad), {Color = frameStroke}):Play()
    
    -- Button animations
    if not cfg.mobile then
        local btnColor = isActive and Color3.fromRGB(255, 70, 70) or Color3.fromRGB(40, 40, 55)
        local btnText = isActive and "PRESS 'P' TO STOP" or "PRESS 'P' TO START"
        
        tws:Create(toggleBtn, TweenInfo.new(0.3, Enum.EasingStyle.Quad), {BackgroundColor3 = btnColor}):Play()
        toggleBtn.Text = btnText
        
        btnGradient.Color = isActive and ColorSequence.new{
            ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 90, 90)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(200, 50, 50))
        } or ColorSequence.new{
            ColorSequenceKeypoint.new(0, Color3.fromRGB(60, 60, 80)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(40, 40, 60))
        }
    end
    
    m.Draggable = not isActive
    m.Active = not isActive
    
    if isActive then
        pulseIndicator()
    end
end

uis.InputBegan:Connect(function(input, gpe)
    if gpe then return end
    if input.KeyCode == cfg.dest and uis:IsKeyDown(Enum.KeyCode.LeftControl) then
        shouldScan = false
        clearConnections()
        sg:Destroy()
    elseif input.KeyCode == cfg.bind then
        cfg.ap = not cfg.ap
        anim(cfg.ap)
        info.Text = cfg.ap and "● AUTOPILOT ACTIVE" or "● WAITING FOR INPUT"
    end
end)

if mobileToggle then
    mobileToggle.MouseButton1Click:Connect(function()
        cfg.ap = not cfg.ap
        anim(cfg.ap)
        
        local mobColor = cfg.ap and Color3.fromRGB(255, 70, 70) or Color3.fromRGB(50, 180, 120)
        tws:Create(mobileToggle, TweenInfo.new(0.3, Enum.EasingStyle.Quad), {BackgroundColor3 = mobColor}):Play()
        
        mobileToggle.Text = cfg.ap and "■ STOP" or "▶ START"
        info.Text = cfg.ap and "● AUTOPILOT ACTIVE" or "● WAITING FOR INPUT"
        
        local mobGrad = mobileToggle:FindFirstChildOfClass("UIGradient")
        if mobGrad then
            mobGrad.Color = cfg.ap and ColorSequence.new{
                ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 90, 90)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(200, 50, 50))
            } or ColorSequence.new{
                ColorSequenceKeypoint.new(0, Color3.fromRGB(50, 200, 130)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(30, 150, 100))
            }
        end
    end)
end

lp.CharacterRemoving:Connect(function()
    clearConnections()
end)

lp.CharacterAdded:Connect(function()
    task.wait(1)
    getSide()
end)

getSide()
task.spawn(scan)

